
const form = document.getElementById("formIMC");

const lista = document.getElementById("listaPessoas");
const pesquisa = document.getElementById("pesquisa");

let pessoas = [];

try {
    pessoas = JSON.parse(localStorage.getItem("pessoas")) || [];
        if (!Array.isArray(pessoas)) pessoas = [];
        } catch {
            pessoas = [];
            }

            // SALVAR DADOS

            function salvarDados() {
                localStorage.setItem("pessoas", JSON.stringify(pessoas));
                }

                // CALCULAR IMC

                function calcularIMC(peso, altura) {
                    return peso / (altura * altura);
                    }

                    // CLASSIFICAÇÃO

                    function classificacao(imc, idade) {

                        if (idade < 20) {
                                return "Avaliação por idade";
                                    }

                                        if (imc < 18.5) return "Abaixo do peso";
                                            if (imc < 25) return "Peso adequado";
                                                if (imc < 30) return "Sobrepeso";
                                                    if (imc < 35) return "Obesidade I";
                                                        if (imc < 40) return "Obesidade II";

                                                            return "Obesidade III";
                                                            }

                                                            // CADASTRAR OU EDITAR

                                                            form.addEventListener("submit", function(event) {

                                                                event.preventDefault();

                                                                    const id = document.getElementById("idPessoa").value;
                                                                        const nome = document.getElementById("nome").value.trim();
                                                                            const idade = Number(document.getElementById("idade").value);
                                                                                const peso = Number(document.getElementById("peso").value);
                                                                                    const altura = Number(document.getElementById("altura").value);

                                                                                        if (
                                                                                                !nome ||
                                                                                                        idade < 1 || idade > 120 ||
                                                                                                                peso <= 0 || peso > 500 ||
                                                                                                                        altura < 0.5 || altura > 2.5
                                                                                                                            ) {
                                                                                                                                    alert("Verifique os dados informados.");
                                                                                                                                            return;
                                                                                                                                                }

                                                                                                                                                    const pessoa = {
                                                                                                                                                            id: id || String(Date.now()),
                                                                                                                                                                    nome,
                                                                                                                                                                            idade,
                                                                                                                                                                                    peso,
                                                                                                                                                                                            altura,
                                                                                                                                                                                                    imc: calcularIMC(peso, altura)
                                                                                                                                                                                                        };

                                                                                                                                                                                                            if (id) {

                                                                                                                                                                                                                    pessoas = pessoas.map(p =>
                                                                                                                                                                                                                                p.id === id ? pessoa : p
                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                            } else {

                                                                                                                                                                                                                                                    pessoas.push(pessoa);

                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                            salvarDados();
                                                                                                                                                                                                                                                                atualizarTela();
                                                                                                                                                                                                                                                                    cancelarEdicao();

                                                                                                                                                                                                                                                                        alert(id ? "Cadastro atualizado!" : "Cadastro realizado!");

                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                        // ATUALIZAR TELA

                                                                                                                                                                                                                                                                        function atualizarTela() {

                                                                                                                                                                                                                                                                            lista.replaceChildren();

                                                                                                                                                                                                                                                                                const busca = pesquisa.value.toLowerCase();

                                                                                                                                                                                                                                                                                    const filtradas = pessoas.filter(p =>
                                                                                                                                                                                                                                                                                            p.nome.toLowerCase().includes(busca)
                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                    filtradas.forEach(p => {

                                                                                                                                                                                                                                                                                                            const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                    const dados = [
                                                                                                                                                                                                                                                                                                                                p.nome,
                                                                                                                                                                                                                                                                                                                                            p.idade,
                                                                                                                                                                                                                                                                                                                                                        p.peso + " kg",
                                                                                                                                                                                                                                                                                                                                                                    p.altura + " m",
                                                                                                                                                                                                                                                                                                                                                                                p.imc.toFixed(2),
                                                                                                                                                                                                                                                                                                                                                                                            classificacao(p.imc, p.idade)
                                                                                                                                                                                                                                                                                                                                                                                                    ];

                                                                                                                                                                                                                                                                                                                                                                                                            dados.forEach(valor => {
                                                                                                                                                                                                                                                                                                                                                                                                                        const td = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                    td.textContent = valor;
                                                                                                                                                                                                                                                                                                                                                                                                                                                linha.appendChild(td);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                const acoes = document.createElement("td");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const editar = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                editar.textContent = "✏️ Editar";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        editar.className = "btn-editar";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                editar.onclick = () => editarPessoa(p.id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const excluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                excluir.textContent = "🗑️ Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        excluir.className = "btn-excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                excluir.onclick = () => excluirPessoa(p.id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes.append(editar, excluir);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                linha.appendChild(acoes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(linha);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("mensagemVazia").style.display =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        filtradas.length ? "none" : "block";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // INDICADORES

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("totalPessoas").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const media = pessoas.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? pessoas.reduce((soma, p) => soma + p.imc, 0) / pessoas.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("imcMedio").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        media.toFixed(2).replace(".", ",");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("ultimoCadastro").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoas.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? pessoas[pessoas.length - 1].nome
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : "Nenhum";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // EDITAR

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function editarPessoa(id) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const pessoa = pessoas.find(p => p.id === id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!pessoa) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("idPessoa").value = pessoa.id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("nome").value = pessoa.nome;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("idade").value = pessoa.idade;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("peso").value = pessoa.peso;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("altura").value = pessoa.altura;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("tituloFormulario").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Editar cadastro";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("btnSalvar").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "💾 Atualizar cadastro";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("btnCancelar").hidden = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        window.scrollTo({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                top: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        behavior: "smooth"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // EXCLUIR

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function excluirPessoa(id) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Tem certeza que deseja excluir este cadastro?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!confirmar) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoas = pessoas.filter(p => p.id !== id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarDados();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarTela();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (document.getElementById("idPessoa").value === id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cancelarEdicao();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // CANCELAR EDIÇÃO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function cancelarEdicao() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                form.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("idPessoa").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("tituloFormulario").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Cadastrar pessoa";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("btnSalvar").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "💾 Salvar cadastro";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("btnCancelar").hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // PESQUISAR

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pesquisa.addEventListener("input", atualizarTela);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("btnCancelar")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .addEventListener("click", cancelarEdicao);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // INICIAR SISTEMA

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarTela();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    